function o(){if(typeof crypto<"u"&&typeof crypto.randomUUID=="function")return crypto.randomUUID();if(typeof crypto<"u"&&typeof crypto.getRandomValues=="function"){const t=crypto.getRandomValues(new Uint8Array(16));t[6]=t[6]&15|64,t[8]=t[8]&63|128;const x=Array.from(t,n=>n.toString(16).padStart(2,"0"));return`${x.slice(0,4).join("")}-${x.slice(4,6).join("")}-${x.slice(6,8).join("")}-${x.slice(8,10).join("")}-${x.slice(10,16).join("")}`}return"xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g,t=>{const x=Math.random()*16|0;return(t==="x"?x:x&3|8).toString(16)})}export{o as g};
